package io.tornado.reporting;
import io.tornado.persistence.*;import io.tornado.persistence.PredictionRepository.ReportRow;import org.junit.jupiter.api.Test;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class BestMixServiceTest{
 @Test void refreshReplacesPreviousRanksAndStoresAtMostTopThreePerSize(){var predictions=mock(PredictionRepository.class);var mixes=mock(BestMethodMixRepository.class);var coins=mock(CoinRepository.class);var settings=mock(AppSettingsRepository.class);Coin coin=new Coin("BTC","BTCUSDT");org.springframework.test.util.ReflectionTestUtils.setField(coin,"id",1L);AppSettings configuration=new AppSettings(900,900);configuration.updateMixSignals(1,new BigDecimal("0.5"),true);when(coins.findById(1L)).thenReturn(Optional.of(coin));when(settings.findById(1)).thenReturn(Optional.of(configuration));List<ReportRow>rows=new ArrayList<>();for(long run=1;run<=6;run++)for(int method=0;method<10;method++)rows.add(row(run,"M"+method,Direction.UP,"101"));when(predictions.findGradedReportRows(1L,900)).thenReturn(rows);new BestMixService(predictions,mixes,coins,settings).refresh(1L,900);verify(mixes).deleteSlice(1L,900,3);@SuppressWarnings("unchecked")org.mockito.ArgumentCaptor<Iterable<BestMethodMix>>capture=org.mockito.ArgumentCaptor.forClass(Iterable.class);verify(mixes).saveAll(capture.capture());List<BestMethodMix>saved=new ArrayList<>();capture.getValue().forEach(saved::add);for(int selectedSize:List.of(2,3,4,5,6,7,8)){List<BestMethodMix>slice=saved.stream().filter(x->x.getMixSize()==selectedSize).toList();assertThat(slice).hasSize(3);assertThat(slice).extracting(BestMethodMix::getRank).containsExactly(1,2,3);}}
 @Test void calculatesEligibleMixesForEverySizeTwoThroughEight(){BestMixService service=service();List<ReportRow>rows=new ArrayList<>();for(long run=1;run<=5;run++)for(int method=0;method<8;method++)rows.add(row(run,"M"+method,Direction.UP,"101"));var result=service.calculate(rows,5);assertThat(result).extracting(BestMixService.Candidate::size).contains(2,3,4,5,6,7,8);assertThat(result).allSatisfy(x->assertThat(x.samples()).isEqualTo(5));assertThat(service.calculate(rows,6)).isEmpty();}
 @Test void wilsonScoreOrdersCandidatesWithoutUsingRawAccuracyAlone(){BestMixService service=service();List<ReportRow>rows=new ArrayList<>();for(long run=1;run<=20;run++){rows.add(row(run,"A",Direction.UP,run<=12?"101":"99"));rows.add(row(run,"B",Direction.UP,run<=12?"101":"99"));rows.add(row(run,"C",Direction.UP,run<=11?"101":"99"));rows.add(row(run,"D",Direction.UP,run<=11?"101":"99"));}var pairs=service.calculate(rows,5).stream().filter(x->x.size()==2).toList();assertThat(pairs).isNotEmpty();assertThat(pairs).isSortedAccordingTo(Comparator.comparingDouble(BestMixService.Candidate::wilson).reversed().thenComparing(Comparator.comparingLong(BestMixService.Candidate::samples).reversed()));}
 private BestMixService service(){return new BestMixService(mock(PredictionRepository.class),mock(BestMethodMixRepository.class),mock(CoinRepository.class),mock(AppSettingsRepository.class));}private ReportRow row(long run,String method,Direction direction,String exit){return new R(run,1L,"BTC","BTCUSDT",method,method,1,Instant.EPOCH.plusSeconds(run),direction,new BigDecimal("100"),900,new BigDecimal(exit),Outcome.CORRECT);}record R(Long runId,Long coinId,String coinSymbol,String coinPair,String methodName,String strategyCode,int strategyVersion,Instant predictedAt,Direction predictedDirection,BigDecimal priceAtPrediction,long horizonSeconds,BigDecimal priceAtGrading,Outcome outcome)implements ReportRow{public Long getRunId(){return runId;}public Long getCoinId(){return coinId;}public String getCoinSymbol(){return coinSymbol;}public String getCoinPair(){return coinPair;}public String getMethodName(){return methodName;}public String getStrategyCode(){return strategyCode;}public int getStrategyVersion(){return strategyVersion;}public Instant getPredictedAt(){return predictedAt;}public Direction getPredictedDirection(){return predictedDirection;}public BigDecimal getPriceAtPrediction(){return priceAtPrediction;}public long getHorizonSeconds(){return horizonSeconds;}public BigDecimal getPriceAtGrading(){return priceAtGrading;}public Outcome getOutcome(){return outcome;}}
}
